#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int sai = 0;
    for (int i = 0; i < n; i++) {
        int tu, sang;
        scanf("%d %d", &tu, &sang);
        int hop_le = (tu == 0 && sang == 1) || (tu == 1 && sang == 2) || (tu == 1 && sang == 3) || (tu == 3 && sang == 1) || (tu == 2 && sang == 0) || (tu == 1 && sang == 4) || (tu == 4 && sang == 2);
        if (!hop_le) sai++;
    }
    printf("%d\n", sai);
    return 0;
}
